// Original work by the same author.
import { err, ok, type Result } from "@zedtech/zedkit-core";
import { HEADER_KEYS } from "./agent-header.js";

/** Start of the marker on line 2 of every generated file; `sync` regenerates only files that carry it. */
export const MARKER_PREFIX = "# generated by zedkit-ai sync from ";

export function markerLine(name: string): string {
  return `${MARKER_PREFIX}.agents/agents/${name}.md and .agents/tokenomics.md; do not edit, run: npx zedkit-ai sync`;
}

/** True when line 2 is a sync marker (line 1 stays `---`, so the file is valid for every loader). */
export function hasMarker(text: string): boolean {
  const lines = text.split("\n", 3);
  return lines[0] === "---" && (lines[1] ?? "").startsWith(MARKER_PREFIX);
}

export type GenerateInput = {
  /** Agent name (the file name without `.md`). */
  name: string;
  /** The source file text from `.agents/agents`. */
  source: string;
  /** The model the route resolved for this provider; `inherit` means "the session's model". */
  model: string;
};

export type Generated = { text: string; notes: string[] };

// A scalar both Cursor and Claude read back unchanged: no quotes, no spaces.
const PLAIN_MODEL = /^[A-Za-z0-9][A-Za-z0-9._-]*$/;
const KEY_LINE = /^([A-Za-z_][A-Za-z0-9_-]*)[ \t]*:/;
const DROPPED: ReadonlySet<string> = new Set(HEADER_KEYS);

type Block = { key: string | undefined; lines: string[] };

// Frontmatter lines grouped per top-level key: a key line plus every line
// after it up to the next key line (nested maps, lists, comments).
function blocks(lines: readonly string[]): Block[] {
  const out: Block[] = [];
  for (const line of lines) {
    const key = KEY_LINE.exec(line)?.[1];
    if (key !== undefined || out.length === 0) out.push({ key, lines: [line] });
    else out[out.length - 1]?.lines.push(line);
  }
  return out;
}

function scalar(block: Block): string {
  return (block.lines[0] ?? "").replace(KEY_LINE, "").trim();
}

/**
 * The tool's copy of an agent: the source with the header blocks removed,
 * `model` set from the route, and the marker on line 2. It splices the
 * frontmatter as text and copies the body byte for byte, so a YAML library
 * upgrade cannot change how `description` is quoted. Pure: the same input
 * gives the same bytes. A `model` the source pins to anything other than
 * `inherit` is the author's choice and is kept as written.
 */
export function generateAgent(input: GenerateInput): Result<Generated> {
  const lines = input.source.replace(/\r\n/g, "\n").replace(/^\uFEFF/, "").split("\n");
  if (lines[0] !== "---") return err(new Error(`${input.name}: missing frontmatter (file must start with ---)`));
  const close = lines.findIndex((line, i) => i > 0 && line.trimEnd() === "---");
  if (close < 0) return err(new Error(`${input.name}: frontmatter is not closed`));
  if (input.model !== "inherit" && !PLAIN_MODEL.test(input.model)) {
    return err(new Error(`${input.name}: model "${input.model}" cannot be written as a plain value (letters, digits, . _ -)`));
  }

  const notes: string[] = [];
  const kept = blocks(lines.slice(1, close).filter((line) => !line.startsWith(MARKER_PREFIX))).filter(
    (block) => block.key === undefined || !DROPPED.has(block.key),
  );
  const at = kept.findIndex((block) => block.key === "model");
  if (at >= 0) {
    const current = scalar(kept[at] as Block);
    if (current === "inherit" || current === "") {
      kept[at] = { key: "model", lines: [`model: ${input.model}`] };
    } else {
      notes.push(`model pinned in source (${current}): route not applied`);
    }
  } else if (input.model !== "inherit") {
    kept.push({ key: "model", lines: [`model: ${input.model}`] });
  }

  const frontmatter = kept.flatMap((block) => block.lines);
  const text = ["---", markerLine(input.name), ...frontmatter, ...lines.slice(close)].join("\n");
  return ok({ text, notes });
}
